<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"; import { Save } from "@lucide/vue"; import { api } from "../api"; import { errorMessage, useUI } from "../ui"; import PageHeader from "../components/PageHeader.vue";
const emit = defineEmits<{ accountChanged: [username: string] }>(); const { notify } = useUI(); const loading = ref(false); const form = reactive({ username: "", currentPassword: "", newPassword: "", confirmPassword: "" });
async function load() { try { form.username = (await api<{ username: string }>("/api/admin/account")).username; form.currentPassword = form.newPassword = form.confirmPassword = ""; } catch (e) { notify(errorMessage(e), "error"); } }
async function save() { if (form.newPassword !== form.confirmPassword) return notify("两次输入的新密码不一致", "error"); loading.value = true; try { await api("/api/admin/account", { method: "PUT", body: { username: form.username, currentPassword: form.currentPassword, newPassword: form.newPassword } }); notify("管理员凭据已更新"); emit("accountChanged", form.username); await load(); } catch (e) { notify(errorMessage(e), "error"); } finally { loading.value = false; } }
onMounted(load);
</script>
<template><PageHeader title="账号安全" subtitle="管理员凭据与登录保护" kicker="SECURITY" /><form class="settings-panel narrow-panel" @submit.prevent="save"><div class="section-title"><div><h2>管理员凭据</h2><span>修改密码后现有登录会话保持有效</span></div><button class="button primary" :disabled="loading"><Save :size="16" />保存</button></div><div class="form-grid one-column"><label class="field">用户名<input v-model="form.username" pattern="[A-Za-z0-9_.-]{3,32}" required autocomplete="username"></label><label class="field">当前密码<input v-model="form.currentPassword" type="password" required autocomplete="current-password"></label><label class="field">新密码<input v-model="form.newPassword" type="password" minlength="12" autocomplete="new-password" placeholder="不修改请留空"></label><label class="field">确认新密码<input v-model="form.confirmPassword" type="password" minlength="12" autocomplete="new-password"></label></div></form></template>
